            "cara:0",
            "drew:7",
            "  ella  :  5  ",
            "frank:hidden:0",
            "gina:bad",
        ];

        assert_eq!(
            collect_visible_scores(&rows),
            vec!["alice=10", "drew=7", "ella=5"]
