    for target in ["backend", "ops", "rust"] {
        let names: Vec<&str> = rows
            .iter()
            .filter(|(_, _, tags)| tags.contains(&target))
            .map(|(name, _, _)| name.as_str())
            .collect();
        out.push(format!("{}={}: {}", target, names.len(), names.join(", ")));
    }

    print!("{}", out.join("\n"));
}

